"""nl — faith_b."""

T = {
"faith_071": ("Wat betekent de naam van Allah «As-Salam»?", ["De Vrede, vrij van elk gebrek", "De Schepper", "De Voorziener", "De Machtige"], "As-Salam behoort tot de namen die aan het einde van soera Al-Hashr worden opgesomd: Hij is de Vrede, vrij van elke onvolkomenheid."),
"faith_072": ("Welke eigenschappen plaatst vers 59:22 naast de naam van Allah, direct na «er is geen god dan Hij»?", ["Kenner van het onwaarneembare en het waarneembare, de Erbarmer", "De Koning en de Krijger", "De Rijke en de Vrijgevige", "De Sterke en de Snelle"], "«Hij is Allah, buiten wie er geen god is, Kenner van het onwaarneembare en het waarneembare. Hij is de Erbarmer, de Meest Barmhartige.»"),
"faith_073": ("Wat gebiedt de Koran te doen met de mooiste namen van Allah?", ["Hem daarmee aan te roepen", "Ze alleen te tellen", "Ze op deuren te schrijven", "Erover te zwijgen"], "«En aan Allah behoren de mooiste namen, roep Hem daarmee dus aan.»"),
"faith_074": ("Hoe stelt soera Ta-Ha de namen van Allah voor?", ["«Allah — er is geen god dan Hij. Aan Hem behoren de mooiste namen»", "«Zijn namen zijn verborgen»", "«Zijn namen zijn ontelbaar»", "«Zijn namen zijn er negen»"], "«Allah — er is geen god dan Hij. Aan Hem behoren de mooiste namen.»"),
"faith_075": ("Welke formulering gebruikt de Koran om elke gelijkenis met Allah uit te sluiten?", ["«Niets is aan Hem gelijk, en Hij is de Alhorende, de Alziende»", "«Hij is de grootste der koningen»", "«Hij is als licht»", "«Niemand ziet Hem»"], "«Niets is aan Hem gelijk, en Hij is de Alhorende, de Alziende.»"),
"faith_076": ("Wat zegt het Troonvers over sluimer en slaap?", ["Sluimer noch slaap overvalt Hem", "Hij slaapt 's nachts", "Hij rust op de zevende dag", "Hij waakt om de dag"], "«Sluimer noch slaap overvalt Hem.»"),
"faith_077": ("Wat zegt de Koran over Allah's kennis van een vallend blad?", ["Er valt geen blad of Hij weet ervan", "Hij verneemt het naderhand", "De engelen lichten Hem in", "Het wordt niet opgeschreven"], "«En bij Hem zijn de sleutels van het onwaarneembare… er valt geen blad of Hij weet ervan.»"),
"faith_078": ("Dan wat is Allah dichter bij de mens, volgens soera Qaf?", ["Dan zijn halsslagader", "Dan zijn schaduw", "Dan zijn stem", "Dan zijn huis"], "«En Wij hebben de mens geschapen en Wij weten wat zijn ziel hem influistert, en Wij zijn dichter bij hem dan zijn halsslagader.»"),
"faith_079": ("Hoe beschrijft de Koran de engelen die over het Vuur zijn aangesteld?", ["Zij gehoorzamen Allah en doen wat hun bevolen wordt", "Sommigen van hen aarzelen", "Zij slapen", "Zij kiezen"], "«…engelen, streng en hard, die Allah niet ongehoorzaam zijn in wat Hij hun beveelt en die doen wat hun bevolen wordt.»"),
"faith_080": ("Hoe beschrijft de Koran de engelen ten opzichte van Allah's woord?", ["Zij gaan Hem niet vóór in het spreken en handelen op Zijn bevel", "Zij betwisten Zijn bevelen", "Zij beslissen zelf", "Zij zwijgen altijd"], "«Nee, zij zijn geëerde dienaren. Zij gaan Hem niet vóór in het spreken, en zij handelen op Zijn bevel.»"),
"faith_081": ("Welke engel noemt de Koran als degene die de openbaring op het hart van de Profeet ﷺ neerbracht?", ["Jibril (Gabriël)", "Mika'il (Michaël)", "Israfil", "Malik"], "«Zeg: wie een vijand is van Jibril — hij is het die haar met toestemming van Allah op jouw hart heeft neergebracht.»"),
"faith_082": ("Welke andere engel wordt naast Jibril genoemd in soera Al-Baqarah?", ["Mikal (Michaël)", "Israfil", "Ridwan", "Munkar"], "«Wie een vijand is van Allah en Zijn engelen en Zijn gezanten en Jibril en Mikal…»"),
"faith_083": ("Welke geloofsobjecten somt vers 4:136 op?", ["Allah, Zijn Gezant, het neergezonden Boek, en de Boeken daarvóór", "Alleen het Boek", "Alleen de profeten", "Alleen de engelen"], "«O jullie die geloven, gelooft in Allah en Zijn Gezant en het Boek dat Hij aan Zijn Gezant heeft neergezonden en de Schrift die Hij daarvóór heeft neergezonden.»"),
"faith_084": ("Welk Boek noemt de Koran als aan Dawud gegeven?", ["De Zabur (de Psalmen)", "De Thora", "Het Evangelie", "De Bladen van Ibrahim"], "«…en Wij gaven aan Dawud de Zabur.»"),
"faith_085": ("Welke soera is genoemd naar de djinn, die de Koran hoorden en geloofden?", ["Al-Jinn", "Al-Insan", "An-Nas", "Al-Furqan"], "«Zeg: aan mij is geopenbaard dat een groep djinn luisterde en zei: wij hebben een wonderbaarlijke recitatie gehoord.»"),
"faith_086": ("Waarvoor werden djinn en mensen geschapen, volgens soera Adh-Dhariyat?", ["Opdat zij Hem aanbidden", "Om de aarde te vullen", "Om te bouwen", "Om te twisten"], "«En Ik heb de djinn en de mensen slechts geschapen om Mij te aanbidden.»"),
"faith_087": ("Wat zegt de Koran over elke ziel en de dood?", ["Elke ziel zal de dood proeven", "Sommige zielen sterven niet", "De dood is een twijfel", "De dood is een eindeloze slaap"], "«Elke ziel zal de dood proeven, en jullie zullen pas op de Dag der Opstanding jullie volle beloning ontvangen.»"),
"faith_088": ("In welke toestand zullen de mensen volgens soera Az-Zalzalah tevoorschijn komen, om hun daden te zien?", ["In verspreide groepen", "Allen samen in één rij", "Slapend", "Zwijgend en onzichtbaar"], "«Op die Dag zullen de mensen in verspreide groepen vertrekken om hun daden getoond te krijgen.»"),
"faith_089": ("Hoe beschrijft soera Al-Kahf het register van daden op de Laatste Dag?", ["Het laat niets kleins of groots onvermeld", "Het noteert alleen grote daden", "Het wordt uitgewist", "Het is door mensen geschreven"], "«Zij zullen zeggen: “Wee ons! Wat is dit voor boek dat niets kleins of groots overslaat zonder het op te tekenen?”»"),
"faith_090": ("Wat zegt de Koran over de ledematen op de Dag des Oordeels?", ["De handen zullen spreken en de voeten zullen getuigen", "Zij zullen zwijgen", "Zij zullen verborgen worden", "Zij zullen veranderd worden"], "«Op die Dag verzegelen Wij hun monden, en hun handen zullen tot Ons spreken en hun voeten zullen getuigen over wat zij plachten te verdienen.»"),
"faith_091": ("Hoe beschrijft de Koran het gebed met betrekking tot zijn tijdstippen?", ["Een voorschrift op vastgestelde tijden", "Vrij op elk uur", "Eens per week", "Alleen 's nachts"], "«Voorwaar, het gebed is de gelovigen op vastgestelde tijden voorgeschreven.»"),
"faith_092": ("Waarvan weerhoudt het gebed, volgens soera Al-'Ankabut?", ["Van zedeloosheid en het verwerpelijke", "Van honger", "Van ziekte", "Van reizen"], "«En onderhoud het gebed: voorwaar, het gebed weerhoudt van zedeloosheid en het verwerpelijke.»"),
"faith_093": ("Welk gebed licht de Koran eruit als «het middelste gebed»?", ["Het wordt genoemd zonder te worden benoemd, in het gebod de gebeden te bewaken", "Alleen het ochtendgebed", "Alleen het avondgebed", "Het vrijdaggebed"], "«Waak zorgvuldig over de gebeden en over het middelste gebed, en sta voor Allah in deemoedige gehoorzaamheid.»"),
"faith_094": ("Om welke reden gebiedt de Koran het gebed, in soera Ta-Ha?", ["Voor het gedenken van Allah", "Voor rust", "Voor de samenkomst", "Om de uren te tellen"], "«Voorwaar, Ik ben Allah. Er is geen god dan Ik, aanbid Mij dus en onderhoud het gebed om Mij te gedenken.»"),
"faith_095": ("Welke hoedanigheid van het gebed opent de lijst van welslagende gelovigen, in Al-Mu'minun?", ["Deemoed (khushu') in het gebed", "De lengte", "De snelheid", "Het aantal"], "«Voorzeker, de gelovigen zullen welslagen: zij die deemoedig zijn in hun gebed.»"),
"faith_096": ("Welk gebed beschrijft soera Al-Isra als «bijgewoond» (mashhudah)?", ["De recitatie bij dageraad", "Het avondgebed", "Het middaggebed", "Het vrijdaggebed"], "«Onderhoud het gebed vanaf het neigen van de zon tot de duisternis van de nacht, en de recitatie bij dageraad: voorwaar, de recitatie bij dageraad wordt bijgewoond.»"),
"faith_097": ("Welke twee zaken gebiedt de Koran als hulp te zoeken?", ["Geduld en gebed", "Kracht en rijkdom", "Reizen en rust", "Zwijgen en afzondering"], "«O jullie die geloven, zoek hulp door geduld en gebed. Voorwaar, Allah is met de geduldigen.»"),
"faith_098": ("Hoeveel rak'ah telt het verplichte Dhuhr-gebed?", ["Vier", "Twee", "Drie", "Vijf"], "Dhuhr, 'Asr en 'Isha tellen elk vier verplichte rak'ah; de scholen zijn het hierover eens."),
"faith_099": ("Welk is het laatste van de vijf verplichte dagelijkse gebeden?", ["Al-'Isha", "Al-Fajr", "Al-Maghrib", "Al-'Asr"], "De volgorde is: Fajr, Dhuhr, 'Asr, Maghrib, 'Isha."),
"faith_100": ("Hoe heet de knielhouding in het gebed?", ["De sujud", "De ruku'", "De qiyam", "De tashahhud"], "Qiyam is het staan, ruku' het buigen, sujud het neerknielen, en tashahhud het zitten van de getuigenis."),
"faith_101": ("Wat voorziet de Koran voor de zieke of de reiziger tijdens Ramadan?", ["Een gelijk aantal dagen om in te halen", "Helemaal niets", "Een dubbele verplichting", "Een eeuwigdurend vasten"], "«Wie van jullie ziek is of op reis, een gelijk aantal andere dagen dan.»"),
"faith_102": ("Welk doel geeft de Koran aan het voorgeschreven vasten?", ["Godvrezendheid (taqwa) bereiken", "Afvallen", "Geld besparen", "Rusten"], "«Het vasten is jullie voorgeschreven zoals het aan hen vóór jullie was voorgeschreven, opdat jullie godvrezend worden.»"),
"faith_103": ("Wat antwoordt Allah, te midden van de verzen over het vasten, aan wie naar Zijn nabijheid vraagt?", ["«Ik ben nabij: Ik verhoor de roep van de roeper wanneer hij Mij aanroept»", "«Wacht de nacht af»", "«Vraag het de engelen»", "«Zoek ver weg»"], "«En wanneer Mijn dienaren jou over Mij vragen: voorwaar, Ik ben nabij. Ik verhoor de smeekbede van de smekeling wanneer hij Mij aanroept.»"),
"faith_104": ("Hoeveel categorieën van zakat-ontvangers somt de Koran op?", ["Acht", "Drie", "Vijf", "Twaalf"], "«De zakat is slechts voor de armen, de behoeftigen, hen die haar innen, hen wier harten gewonnen moeten worden, voor het vrijkopen van gevangenen, voor de schuldenaars, op de weg van Allah, en voor de reiziger.»"),
"faith_105": ("Welk effect schrijft de Koran toe aan de zakat die van het vermogen wordt genomen?", ["Zij reinigt en doet groeien", "Zij verarmt", "Zij is symbolisch", "Zij vervangt het gebed"], "«Neem van hun bezittingen een aalmoes waarmee jij hen reinigt en hen doet groeien.»"),
"faith_106": ("Welke twee verplichtingen koppelt de Koran het vaakst samen?", ["Het gebed en de zakat", "Vasten en reizen", "Bedevaart en handel", "Lezen en schrijven"], "«En onderhoud het gebed en geef de zakat; al het goede dat jullie voor jezelf vooruitzenden, zullen jullie bij Allah terugvinden.»"),
"faith_107": ("Wat zegt de Koran dat Allah bereikt bij het offer?", ["Noch het vlees noch het bloed, maar de godvrezendheid van de gelovige", "Alleen het vlees", "Alleen het bloed", "Het aantal dieren"], "«Hun vlees zal Allah niet bereiken, noch hun bloed, maar wat Hem bereikt is godvrezendheid van jullie kant.»"),
"faith_108": ("Wat is de beste proviand voor de bedevaart, volgens de Koran?", ["Godvrezendheid (taqwa)", "Goud", "Voedsel", "Rijdieren"], "«En neem proviand mee, maar voorwaar, de beste proviand is godvrezendheid.»"),
"faith_109": ("Welke ritus noemt de Koran rond het Aloude Huis?", ["De omgang (tawaf)", "Het rennen in de woestijn", "Het beklimmen van een heuvel", "Het vasten ter plaatse"], "«…en laat hen de tawaf rond het Aloude Huis verrichten.»"),
"faith_110": ("Waar gebiedt de Koran Allah te gedenken, na het vertrek uit 'Arafat?", ["Bij al-Mash'ar al-Haram, in Muzdalifah", "Op de berg Uhud", "In Quba", "In Ta'if"], "«Maar wanneer jullie van 'Arafat vertrekken, gedenk dan Allah bij al-Mash'ar al-Haram.»"),
"faith_111": ("Welk soort berouw vraagt de Koran van de gelovigen?", ["Een oprecht berouw (tawbah nasuh)", "Een schriftelijk berouw", "Een openbaar berouw", "Een jaarlijks berouw"], "«O jullie die geloven, keer tot Allah terug met oprecht berouw.»"),
"faith_112": ("Wat zegt soera Ash-Shura over de aanvaarding van berouw?", ["Hij is het die het berouw van Zijn dienaren aanvaardt en de misstappen vergeeft", "Berouw wordt niet aanvaard", "Er is een tussenpersoon nodig", "Men moet een jaar wachten"], "«En Hij is het die het berouw van Zijn dienaren aanvaardt en de misstappen vergeeft, en Hij weet wat jullie doen.»"),
"faith_113": ("Wat doen zij die de Koran prijst nadat zij een fout hebben begaan?", ["Zij gedenken Allah en vragen om vergeving", "Zij vluchten", "Zij zwijgen", "Zij geven anderen de schuld"], "«En zij die, wanneer zij een zedeloosheid begaan of zichzelf onrecht aandoen, Allah gedenken en om vergeving voor hun zonden vragen.»"),
"faith_114": ("Hoe vaak gebiedt de Koran het gedenken van Allah, in soera Al-Ahzab?", ["Veelvuldig, 's ochtends en 's avonds", "Eens per jaar", "Eens per week", "Alleen onderweg"], "«O jullie die geloven, gedenk Allah met veelvuldig gedenken, en prijs Hem 's ochtends en 's avonds.»"),
"faith_115": ("Waarover denken «de bezitters van verstand» na, aan het einde van soera Al-'Imran?", ["Over de schepping van de hemelen en de aarde, in elke houding", "Over de oogsten", "Over de karavanen", "Over de geslachtslijnen"], "«Zij die Allah gedenken staand, zittend en op hun zij liggend, en nadenken over de schepping van de hemelen en de aarde.»"),
"faith_116": ("Wat gebiedt de Koran te doen zodra een besluit genomen is?", ["Zijn vertrouwen op Allah stellen", "Op een teken wachten", "Een waarzegger raadplegen", "Opgeven"], "«En wanneer je een besluit hebt genomen, stel dan je vertrouwen op Allah. Voorwaar, Allah houdt van hen die op Hem vertrouwen.»"),
"faith_117": ("Naar wie richt soera Ash-Sharh het verlangen, wanneer de taak volbracht is?", ["Naar zijn Heer", "Naar rust", "Naar de familie", "Naar de mensen"], "«Wanneer je dan klaar bent, sta op, en richt je verlangen tot je Heer.»"),
"faith_118": ("Waarmee vergelijkt soera Al-Hadid het leven van deze wereld?", ["Regen waarvan de groei behaagt, dan geel wordt en tot gruis vergaat", "Een lange reis", "Een berg", "Een oceaan"], "«Weet dat het leven van deze wereld slechts vermaak is… als het voorbeeld van regen waarvan de plantengroei de landbouwers behaagt; dan verdort zij en zie je haar geel worden, waarna zij gruis wordt.»"),
"faith_119": ("Wat verklaart de Koran beter dan rijkdom en kinderen, de tooi van deze wereld?", ["De blijvende goede daden", "Goud", "Roem", "Land"], "«Rijkdom en kinderen zijn de tooi van het wereldse leven, maar de blijvende goede daden zijn bij jouw Heer beter als beloning.»"),
"faith_120": ("Welke vraag stelt de Koran over het doel van de schepping van de mens?", ["«Dachten jullie dat Wij jullie zonder doel hebben geschapen?»", "«Wie heeft jullie genoemd?»", "«Waar gaan jullie heen?»", "«Met hoevelen zijn jullie?»"], "«Dachten jullie dan dat Wij jullie zinloos hebben geschapen en dat jullie niet tot Ons zouden terugkeren?»"),
"faith_121": ("Welke belofte doet de Koran aan wie Allah gedenkt?", ["«Gedenk Mij; Ik zal jullie gedenken»", "«Je zult rijk zijn»", "«Je zult lang leven»", "«Je zult reizen»"], "«Gedenk Mij dus; Ik zal jullie gedenken. En wees Mij dankbaar en wees Mij niet ondankbaar.»"),
"faith_122": ("Aan wie gebiedt de Koran geschillen voor te leggen?", ["Aan Allah en de Gezant ﷺ", "Aan de ouderen", "Aan de markt", "Aan de dichters"], "«En als jullie over iets van mening verschillen, leg het dan voor aan Allah en de Gezant, als jullie in Allah en de Laatste Dag geloven.»"),
"faith_123": ("Hoe beschrijft soera Al-Anfal de harten van de gelovigen bij het noemen van Allah?", ["Hun harten beven, en hun geloof neemt toe bij de recitatie", "Zij verharden", "Zij vallen in slaap", "Zij vergeten"], "«De gelovigen zijn slechts zij van wie de harten sidderen wanneer Allah genoemd wordt, en wanneer Zijn verzen aan hen worden voorgedragen, neemt hun geloof toe.»"),
"faith_124": ("Wat gebiedt de Koran volledig aan de Heer der werelden te wijden?", ["Het gebed, de riten, het leven en het sterven", "De handel", "De oogsten", "De reizen"], "«Zeg: voorwaar, mijn gebed, mijn offerriten, mijn leven en mijn sterven zijn voor Allah, Heer der werelden.»"),
"faith_125": ("Welke voorwaarde stelt soera Al-Bayyinah aan de geboden aanbidding?", ["Allah oprecht te aanbidden, Hem de godsdienst zuiver toe te wijden", "In het openbaar te aanbidden", "Schriftelijk te aanbidden", "Alleen in groepen te aanbidden"], "«En hun werd slechts bevolen Allah te aanbidden, Hem zuiver in de godsdienst toegewijd, het gebed te onderhouden en de zakat te geven.»"),
"faith_126": ("Wat beschrijft de Koran als stromend in de tuinen die de godvrezenden zijn beloofd?", ["Rivieren", "Wegen", "Bruggen", "Putten"], "De Koran beschrijft de tuinen herhaaldelijk als «waar onderdoor de rivieren stromen»."),
"faith_127": ("Wat zegt de Koran over wat als beloning voor de gelovigen verborgen is?", ["Geen ziel weet welke verkoeling van de ogen voor hen is weggelegd", "Alles wordt uitvoerig beschreven", "Het zijn rijkdommen", "Het zijn koninkrijken"], "«En geen ziel weet welke verkoeling van de ogen voor hen verborgen is als beloning voor wat zij plachten te doen.»"),
"faith_128": ("Wat belooft de Koran aan hen die goed doen, naast de beste beloning?", ["Nog meer daarbij (ziyadah)", "Uitstel", "Een koninkrijk", "Een boek"], "«Voor hen die goed hebben gedaan is de beste beloning en nog meer.»"),
"faith_129": ("Hoe beschrijft de Koran het onthaal van de godvrezenden aan de poort van het Paradijs?", ["«Vrede zij met jullie; jullie zijn rein geworden, treed dus binnen om er eeuwig te blijven»", "In stilte", "Na een lange beproeving", "Een voor een zonder een woord"], "«De bewakers ervan zullen zeggen: “Vrede zij met jullie; jullie zijn goed geweest, treed dus binnen om er eeuwig te blijven.”»"),
"faith_130": ("Waarheen gebiedt de Koran zich te haasten, in soera Al-'Imran?", ["Naar vergeving van de Heer en een Paradijs zo wijd als de hemelen en de aarde", "Naar de markt", "Naar de reis", "Naar rijkdom"], "«En haast jullie naar vergeving van jullie Heer en naar een tuin zo wijd als de hemelen en de aarde, bereid voor de godvrezenden.»"),
"faith_131": ("Welke verantwoordelijkheid legt de Koran de gelovige op tegenover zijn gezin?", ["Hen, en zichzelf, te beschermen tegen een Vuur", "Hen rijk te maken", "Hun talen te leren", "Hen mee op reis te nemen"], "«O jullie die geloven, bescherm jezelf en jullie families tegen een Vuur waarvan de brandstof mensen en stenen zijn.»"),
"faith_132": ("Hoe omschrijft vers 2:177 de ware vroomheid (al-birr)?", ["Geloof in Allah, de Laatste Dag, de engelen, het Boek en de profeten, en het geven van zijn bezit", "Het gezicht naar het oosten of het westen wenden", "Alleen vasten", "Reizen"], "«Vroomheid is niet dat jullie je gezichten naar het oosten of het westen wenden, maar vroom is wie gelooft in Allah, de Laatste Dag, de engelen, het Boek en de profeten.»"),
"faith_133": ("Wie zal de verrichte daden zien, volgens soera At-Tawbah?", ["Allah, Zijn Gezant ﷺ en de gelovigen", "Niemand", "Alleen de engelen", "De koningen"], "«En zeg: werk, want Allah zal jullie daden zien, en Zijn Gezant en de gelovigen.»"),
"faith_134": ("Met welke uitspraak eindigt soera Al-Ikhlas?", ["«En niemand is aan Hem gelijkwaardig»", "«Hij is de grootste»", "«Hij is nabij»", "«Hij is de eerste»"], "«En niemand is aan Hem gelijkwaardig.»"),
"faith_135": ("Welke vier namen brengt soera Al-Hadid in één vers samen?", ["De Eerste, de Laatste, de Zichtbare en de Verborgene", "De Koning, de Heilige, de Vrede, de Getrouwe", "De Schepper, de Voortbrenger, de Vormgever, de Wijze", "De Levende, de Zelfbestaande, de Horende, de Ziende"], "«Hij is de Eerste en de Laatste, de Zichtbare en de Verborgene, en Hij is Alwetend over alle dingen.»"),
"faith_136": ("Welke namen somt het einde van soera Al-Hashr op na «de Heerser»?", ["De Heilige, de Vrede, de Schenker van veiligheid, de Toezichthouder", "De Schepper, de Vormgever", "De Vergevende, de Barmhartige", "De Horende, de Ziende"], "«Hij is Allah, de Heerser, de Heilige, de Vrede, de Schenker van veiligheid, de Toezichthouder, de Almachtige.»"),
"faith_137": ("Hoe heet de formule «Er is geen god dan Allah, Mohammed is Zijn Gezant»?", ["De shahadah (de geloofsgetuigenis)", "De basmalah", "De takbirah", "De tasmiyah"], "De shahadah is het eerste woord van de islam en de eerste van haar zuilen."),
"faith_138": ("Hoe heet de formule «Allahu akbar»?", ["De takbir", "De tahlil", "De tasbih", "De tahmid"], "Takbir is «Allahu akbar», tasbih is «subhan Allah», tahmid is «al-hamdu lillah», en tahlil is «la ilaha illa-llah»."),
"faith_139": ("Hoe heet de formule «In de naam van Allah, de Erbarmer, de Meest Barmhartige»?", ["De basmalah", "De hamdalah", "De hawqalah", "De istirja'"], "De basmalah opent elke soera op één na; de hawqalah is «la hawla wa la quwwata illa billah»."),
"faith_140": ("Welke woorden leert de Koran te zeggen wanneer een ramp toeslaat?", ["«Voorwaar, wij behoren aan Allah, en tot Hem keren wij terug»", "«Waarom ik?»", "«Het gaat voorbij»", "«Het is het lot van de mensen»"], "«Zij die, wanneer een ramp hen treft, zeggen: “Voorwaar, wij behoren aan Allah, en voorwaar, tot Hem keren wij terug.”»"),
"faith_141": ("Wat gebiedt de Koran te zeggen bij het aankondigen van een handeling voor morgen?", ["«Als Allah het wil» (in sha' Allah)", "«Het is beloofd»", "«Zonder mankeren»", "«Ik zweer het»"], "«En zeg nooit over iets: “Voorwaar, ik zal dat morgen doen”, behalve met de toevoeging: “Als Allah het wil.”»"),
"faith_142": ("Welke kennis behoudt de Koran aan Allah alleen voor, aan het einde van soera Luqman?", ["Het Uur, de regen, wat in de baarmoeders is, wat men morgen zal verwerven, en waar men zal sterven", "Het aantal sterren", "De namen van koningen", "Het tellen van de dagen"], "«Voorwaar, Allah heeft kennis van het Uur en Hij zendt de regen neer en weet wat in de baarmoeders is. En geen ziel weet wat zij morgen zal verwerven, en geen ziel weet in welk land zij zal sterven.»"),
"faith_143": ("Wat zegt de Koran over de termijn die voor elke gemeenschap is vastgesteld?", ["Wanneer hij komt, wordt hij geen uur uitgesteld of vervroegd", "Hij kan veranderd worden", "Hij is Allah onbekend", "Hij hangt van koningen af"], "«En voor elke gemeenschap is er een termijn. Wanneer hun termijn komt, kunnen zij geen uur achterblijven, noch vooruitlopen.»"),
"faith_144": ("Wat belooft de Koran aan wie goed doet, man of vrouw, terwijl hij gelooft?", ["Een goed leven, en een beloning naar het beste van hun daden", "Rijkdom", "Macht", "Roem"], "«Wie rechtschapen handelt, man of vrouw, terwijl hij gelovig is — Wij zullen hem zeker een goed leven doen leiden.»"),
"faith_145": ("Welk onderscheid maakt de Koran tussen «islam» en «geloof» in soera Al-Hujurat?", ["Zeggen «wij hebben ons overgegeven» is nog geen geloof dat de harten is binnengetreden", "Het zijn dezelfde woorden", "Geloof komt altijd eerst", "Islam is alleen voor geleerden"], "«De bedoeïenen zeggen: “Wij geloven.” Zeg: “Jullie geloven niet; zeg liever: wij hebben ons overgegeven, want het geloof is nog niet jullie harten binnengetreden.”»"),
"faith_146": ("Welke regel stelt soera Al-Ma'idah over één enkel leven?", ["Wie één mens doodt, is alsof hij de hele mensheid doodt; wie er één redt, alsof hij allen redt", "Elk leven telt als één", "Alleen verwanten tellen", "Alleen aantallen tellen"], "«Wie een ziel doodt, anders dan voor een ziel of voor verderf op aarde, is alsof hij de hele mensheid heeft gedood; en wie er één redt, is alsof hij de hele mensheid heeft gered.»"),
"faith_147": ("Met hoeveel vermenigvuldigt de Koran de beloning van een goede daad?", ["Tienvoudig", "Tweevoudig", "Honderdvoudig", "Zij wordt niet vermenigvuldigd"], "«Wie met een goede daad komt, krijgt tienmaal het gelijke daarvan; en wie met een slechte daad komt, wordt slechts met het gelijke daarvan vergolden.»"),
"faith_148": ("Hoe beschrijft soera Fatir de verhouding van de mensen tot Allah?", ["Zij zijn de behoeftigen die Hem nodig hebben, terwijl Allah de Behoefteloze is, de Geprezene", "Zij zijn Zijn deelgenoten", "Zij zijn onafhankelijk", "Zij zijn Zijn schuldeisers"], "«O mensen, jullie zijn het die Allah nodig hebben, terwijl Allah de Behoefteloze is, de Geprezene.»"),
"faith_149": ("Welke vier eigenschappen redden van verlies, volgens soera Al-'Asr?", ["Geloof, goede daden, elkaar aansporen tot de waarheid en tot geduld", "Rijkdom, kracht, schoonheid, sluwheid", "Zwijgen, slapen, afzondering, vasten", "Reizen, handel, schrijven, lezen"], "«Bij de tijd, de mens lijdt verlies, behalve zij die geloven en goede daden verrichten en elkaar aansporen tot de waarheid en elkaar aansporen tot geduld.»"),
"faith_150": ("Waarin verklaren de gelovigen te geloven, in het voorlaatste vers van soera Al-Baqarah?", ["In Allah, Zijn engelen, Zijn boeken en Zijn gezanten", "In één boek", "In één engel", "In hun voorvaderen"], "«De Gezant gelooft in wat aan hem van zijn Heer is neergezonden, en zo ook de gelovigen. Allen geloven in Allah en Zijn engelen en Zijn boeken en Zijn gezanten.»"),
}
